import crypto from 'node:crypto';
import { getAdminClient } from '../config/pocketbase.js';
import { env } from '../config/env.js';

/**
 * ShopFinder — Listing View Tracking Service (Phase 12, Task 12.1)
 *
 * Implements server-side, privacy-preserving page-view logging in the dedicated
 * `listing_views` PocketBase collection.
 *
 * Requirements:
 * 1. Only record views on approved public listings.
 * 2. Never record views generated by the listing's own owner or admin reviewers.
 * 3. Never store raw IP addresses — hash IPs using SHA-256 with a secure salt.
 * 4. Deduplicate rapid repeated views within a 30-minute sliding window.
 * 5. Fail-safe execution: tracking failures must never fail the listing detail HTTP request.
 */

const DEDUPLICATION_WINDOW_MS = 30 * 60 * 1000; // 30 minutes

/**
 * Generates a one-way cryptographic SHA-256 hash of a client IP address.
 *
 * @param {string} ip
 * @returns {string} Hex-encoded hash
 */
export function hashIp(ip) {
  if (!ip || typeof ip !== 'string') return '';
  const salt = env.SESSION_SECRET || 'sf_view_hash_salt';
  return crypto.createHash('sha256').update(`${ip.trim()}:${salt}`).digest('hex');
}

/**
 * Records a page-view event for an approved commercial listing.
 *
 * @param {Object} params
 * @param {string} params.listingId - 15-char PocketBase listing ID
 * @param {string} params.listingOwnerId - ID of the listing owner
 * @param {string} params.status - Current listing moderation status ('approved', etc.)
 * @param {Object} [params.user=null] - Authenticated user context (if any)
 * @param {string} [params.ip=''] - Client IP address
 * @param {string} [params.userAgent=''] - Client user agent string
 * @returns {Promise<{ recorded: boolean, reason?: string, id?: string }>}
 */
export async function recordListingView({
  listingId,
  listingOwnerId,
  status,
  user = null,
  ip = '',
  userAgent = '',
}) {
  try {
    // 1. Only record views for published/approved listings
    if (status !== 'approved') {
      return { recorded: false, reason: 'unapproved_listing' };
    }

    // 2. Prevent invalid or malformed listing ID
    if (!listingId || typeof listingId !== 'string' || !/^[a-zA-Z0-9]{15}$/.test(listingId.trim())) {
      return { recorded: false, reason: 'invalid_listing_id' };
    }

    const cleanListingId = listingId.trim();

    // 3. Do not count owner viewing their own listing
    const viewerId = user?.id || null;
    if (viewerId && listingOwnerId && viewerId === listingOwnerId) {
      return { recorded: false, reason: 'owner_self_view' };
    }

    // 4. Do not count admin platform inspection / review views
    if (user?.role === 'admin') {
      return { recorded: false, reason: 'admin_preview' };
    }

    const ipHash = hashIp(ip);
    const sanitizedUserAgent = typeof userAgent === 'string' ? userAgent.slice(0, 255) : '';
    // Format cutoff time with space to match PocketBase SQLite datetime format
    const cutoffTime = new Date(Date.now() - DEDUPLICATION_WINDOW_MS).toISOString().replace('T', ' ');

    const pb = await getAdminClient();

    // 5. Deduplication check within sliding window
    // For authenticated viewers, check by viewer ID; for anonymous viewers, check by ip_hash
    if (viewerId) {
      const existing = await pb.collection('listing_views').getList(1, 1, {
        filter: pb.filter('listing = {:listingId} && viewer = {:viewerId} && viewed_at >= {:cutoff}', {
          listingId: cleanListingId,
          viewerId,
          cutoff: cutoffTime,
        }),
        requestKey: null,
      });

      if (existing.items.length > 0) {
        return { recorded: false, reason: 'deduplicated_auth_viewer' };
      }
    } else if (ipHash) {
      const existing = await pb.collection('listing_views').getList(1, 1, {
        filter: pb.filter('listing = {:listingId} && ip_hash = {:ipHash} && viewed_at >= {:cutoff}', {
          listingId: cleanListingId,
          ipHash,
          cutoff: cutoffTime,
        }),
        requestKey: null,
      });

      if (existing.items.length > 0) {
        return { recorded: false, reason: 'deduplicated_ip_viewer' };
      }
    }

    // 6. Record the view event
    const record = await pb.collection('listing_views').create(
      {
        listing: cleanListingId,
        viewer: viewerId,
        ip_hash: ipHash,
        user_agent: sanitizedUserAgent,
        viewed_at: new Date().toISOString(),
      },
      { requestKey: null }
    );

    return { recorded: true, id: record.id };
  } catch (err) {
    // Fail-safe: Never propagate internal errors to user request
    return { recorded: false, reason: 'internal_error', error: err.message };
  }
}
